/* Scoped base for Quartz. Replaces Tailwind preflight inside .quartz only; imported before the utilities. */

.quartz {
  min-height: 100dvh;
  background: var(--surface-canvas);
  color: var(--text-1);
  font: var(--type-body);
  font-variation-settings: var(--width-normal);
  letter-spacing: var(--tracking-text);
  text-wrap: pretty;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  /* Light here; tokens.css sets dark on the dark theme and ink surfaces, and light again on paper inside them. */
  color-scheme: light;
}
/* The reset sits in the base layer, beside Tailwind's own preflight, so a project's layered utilities (mx-auto,
   px-4) beat it, and Quartz's unlayered ones still do. What must win over a page's own rules stays out of the layer:
   the scope element, prose links, the selection colour, the focus ring and the iOS zoom guard. */
@layer base {
  .quartz :where(*, ::before, ::after) { box-sizing: border-box; border: 0 solid var(--line-row); margin: 0; padding: 0; }
  .quartz :where(h1, h2, h3, h4, h5, h6, p, figure, blockquote, dl, dd, pre) { margin: 0; font: inherit; }
  .quartz :where(ul, ol) { list-style: none; }
  .quartz :where(a) { color: inherit; text-decoration: inherit; }
  .quartz :where(button, input, select, textarea) { font: inherit; letter-spacing: inherit; color: inherit; background: transparent; }
  .quartz :where(button, [role="button"]) { cursor: pointer; }
  .quartz :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  /* max-width: 100% shrinks an SVG layer with no width of its own (a 0x0 overflow-visible overlay) to nothing,
     so an SVG marked overflow-visible skips it. Any other SVG layer that must overflow its box takes max-w-none. */
  .quartz :where(img, video, canvas, svg:not(.overflow-visible, [overflow="visible"])) { display: block; max-width: 100%; }
  .quartz :where(svg.overflow-visible, svg[overflow="visible"]) { display: block; }
  .quartz :where(table) { border-collapse: collapse; }
  .quartz :where(code, kbd, samp, pre) { font-family: var(--font-mono); }
  /* Every duration, count and value lines up: tabular figures in table cells and time and data elements. */
  .quartz :where(td, th, time, data, output) { font-variant-numeric: tabular-nums; }
  /* Every interactive element declares its transition, so no control cuts while its neighbour tweens.
     Hover is 120ms (--dur-fast) on the standard curve; a press answers in 60ms (--dur-press). Components override at will. */
  .quartz :where(a, button, summary, input, select, textarea, label, [role="button"], [role="tab"], [role="menuitem"], [role="option"], [role="switch"], [role="checkbox"], [role="radio"]) {
    transition-property: color, background-color, border-color, outline-color, text-decoration-color, box-shadow, opacity;
    transition-duration: var(--dur-fast);
    transition-timing-function: var(--ease-step);
  }
  .quartz :where(a, button, [role="button"]):where(:active) { transition-duration: var(--dur-press); }
}
/* Prose links (inside [data-prose]) are underlined at rest: 1px at a 4px offset in text-3, darkening to ink
   on hover. Their focus ring hugs the text with the soft corner and 2px of side padding. */
.quartz :where([data-prose]) a:where(:not([data-slot])) {
  text-decoration: underline 1px var(--text-3);
  text-underline-offset: 4px;
  border-radius: var(--radius-soft);
  padding-inline: 2px;
  margin-inline: -2px;
}
@media (hover: hover) { .quartz :where([data-prose]) a:where(:not([data-slot])):hover { text-decoration-color: var(--ink); color: var(--text-1); } }
.quartz ::selection { background: var(--hue-3-field); color: var(--text-on-field); }
/* The ring's colour is set at rest, so an element that transitions outline-color never fades its ring in from
   the text colour. */
.quartz :where(*, ::before, ::after) { outline-color: var(--border-focus); }
/* Focus is always a --line-focus outline in --border-focus, --focus-offset out: one treatment for every element.
   Two classes of specificity beat an app's global a:focus-visible. Where the ring must sit elsewhere, the focus-ring
   and focus-ring-inset utilities (styles.css) draw the same ring. */
.quartz :where(*):is(:focus-visible, [data-force-focus-visible]) { outline: var(--line-focus) solid var(--border-focus); outline-offset: var(--focus-offset); }
/* A bare control inside a box ([data-control]) draws no ring: the box turns its edge ink with has-[[data-control]:focus],
   so the icons and units in the box sit inside the ring (trap/field-affix-focus). */
.quartz :where([data-control]):is(:focus-visible, [data-force-focus-visible]) { outline: none; }

/* iOS WebKit zooms the page when a field under 16px takes focus. On a coarse pointer every text field is at
   least 16px, whatever its type role says. Two classes of specificity beat a type-* utility on the field. */
@media (pointer: coarse) {
  .quartz input:not([type="checkbox"], [type="radio"], [type="range"], [type="button"], [type="submit"], [type="file"], [type="color"]),
  .quartz textarea,
  .quartz select { font-size: max(16px, 1em); }
}

/* Quartz's Tailwind entry. Import it once, in the root layout, as its own stylesheet, and put the quartz class
   on the element that holds Quartz UI (usually body).

   Scoping, so none of this reaches the rest of your app:
   - No preflight. base.css applies inside .quartz only.
   - The theme is `inline reference`: utilities compile to var(--quartz-token) and nothing is written to
     :root, so your own --color-*, --space-* and --font-* tokens stay as they are.
   - Utilities come only from the folders the @source lines name (source(none)). Installed in a project, those are
     Quartz's folders and the project's app, pages, src and components, so a Quartz class in your own code works,
     and the utilities are nested under :where(.quartz, [data-system="quartz"]), so none reaches markup outside it.
   - base.css comes before the utilities, so a utility beats a base rule of the same specificity.
   - Utilities are unlayered on purpose. Unlayered rules beat every layer, so layered utilities would lose
     to an app's unlayered global `a` and `button` rules. */

@import "./tokens.css";
@import "./base.css";
:where(.quartz, [data-system="quartz"]) {
  @tailwind utilities source(none);
}

@source "../../app";
@source "../../pages";
@source "../../src";
@source "../../components";
@source "../../lib/quartz";
@source not "../../lib/quartz/lint";

/* dark: matches wherever the ink channel is light: in the dark theme, set on .quartz or on an ancestor as
   [data-theme="dark"] or an app's .dark, and inside ink. .quartz[data-theme="light"] under a dark ancestor stays
   light. An inverse surface is dark on a light page and light in the dark theme or inside ink, so it joins the
   first list and leaves through the last :not(). */
@custom-variant dark (&:where(:is(:is([data-theme="dark"], [data-theme="dark"] *, .dark *):not(.quartz[data-theme="light"], .quartz[data-theme="light"] *), [data-surface="ink"], [data-surface="ink"] *, [data-surface="inverse"], [data-surface="inverse"] *):not(:is(.quartz[data-theme="dark"], :is([data-theme="dark"], .dark) .quartz:not([data-theme="light"]), [data-surface="ink"]) :is([data-surface="inverse"], [data-surface="inverse"] *))));

/* A component's state can be shown without the pointer or keyboard, for a style guide, a story or a screenshot
   test, by setting data-force-hover, data-force-focus, data-force-focus-visible or data-force-active on its
   root. These variants answer to the attribute as well as the real pseudo-class, so a forced state is the
   component's own style, never a copy that drifts. Hover keeps Tailwind's guard: it only fires on devices that can hover.
   Because they are selector variants, the compound forms answer too: has-focus-visible: matches a
   descendant carrying data-force-focus-visible, and group-hover/x: a group carrying data-force-hover. */
@custom-variant hover { @media (hover: hover) { &:hover { @slot; } } &[data-force-hover] { @slot; } }
@custom-variant focus { &:focus { @slot; } &[data-force-focus] { @slot; } }
@custom-variant focus-visible { &:focus-visible { @slot; } &[data-force-focus-visible] { @slot; } }
@custom-variant active { &:active { @slot; } &[data-force-active] { @slot; } }

/* touch: a screen with no hover or a coarse pointer, one spelling for both checks (touch:opacity-100, touch:hidden). */
@custom-variant touch { @media (hover: none) { @slot; } @media (pointer: coarse) { @slot; } }

/* A wrapper with data-force-reduced-motion shows its contents as under reduced motion, for the same uses.
   motion-reduce: answers to it as well as the media query, motion-safe: stands down under it,
   and tokens.css zeroes the same durations there as under the query. Forced colors has no such hook:
   the browser repaints with system colors and drops backgrounds and shadows, which CSS cannot imitate,
   so forced-colors stays a media variant and is checked with browser emulation. */
@custom-variant motion-reduce { @media (prefers-reduced-motion: reduce) { @slot; } &:where([data-force-reduced-motion], [data-force-reduced-motion] *) { @slot; } }
@custom-variant motion-safe { @media (prefers-reduced-motion: no-preference) { &:not(:where([data-force-reduced-motion], [data-force-reduced-motion] *)) { @slot; } } }

@theme inline reference {
  --*: initial;

  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;

  /* Container widths for max-w-* and @container variants. --*: initial removes Tailwind's defaults,
     so they are declared again here, at Tailwind's values. */
  --container-3xs: 16rem;
  --container-2xs: 18rem;
  --container-xs: 20rem;
  --container-sm: 24rem;
  --container-md: 28rem;
  --container-lg: 32rem;
  --container-xl: 36rem;
  --container-2xl: 42rem;
  --container-3xl: 48rem;
  --container-4xl: 56rem;
  --container-5xl: 64rem;
  --container-6xl: 72rem;
  --container-7xl: 80rem;
  --container-field-group: 448px; /* width where responsive fields sit side by side | field */
  --container-popup: var(--popup-max); /* tallest a list popup grows before it scrolls | select, combobox, menu */
  --container-overlay-sm: var(--overlay-sm);
  --container-overlay: var(--overlay);
  --container-overlay-lg: var(--overlay-lg);
  --container-popover: var(--popover);
  --container-toast: var(--toast-width);

  /* Tailwind's other theme-backed families that --*: initial wiped and that Quartz pages use: aspect-video
     (a 16:9 skeleton or media area) and leading-tight. aspect-square and the other fixed ratios need no
     theme value. */
  --aspect-video: 16 / 9;
  --leading-tight: 1.25;

  /* 4px base: p-1 is --space-1, p-4 is --space-4. */
  --spacing: var(--space-1);

  /* The semantic names generic components expect (background, card, muted, accent), pointed at Quartz roles. A card is still the grey field until Card becomes the frame;
     muted is the well. */
  --color-background: var(--surface-page);
  --color-foreground: var(--text-1);
  --color-card: var(--surface-card);
  --color-card-foreground: var(--text-1);
  --color-popover: var(--surface-raised);
  --color-popover-foreground: var(--text-1);
  --color-primary: var(--button-primary);
  --color-primary-foreground: var(--text-inverse);
  --color-secondary: var(--button-secondary);
  --color-secondary-foreground: var(--text-1);
  --color-muted: var(--surface-card);
  --color-muted-foreground: var(--text-2);
  --color-accent: var(--surface-hover);
  --color-accent-foreground: var(--text-1);
  --color-destructive: var(--fail-mark);
  --color-destructive-foreground: var(--text-on-field);
  --color-border: var(--line-row);
  --color-input: var(--line-control);
  --color-ring: var(--border-focus);
  --color-sidebar: var(--surface-page);
  --color-sidebar-foreground: var(--text-1);
  --color-sidebar-accent: var(--surface-hover);
  --color-sidebar-border: var(--border-hair);

  /* Quartz's own roles. */
  --color-paper: var(--paper);
  --color-ink: var(--ink);
  --color-page: var(--surface-page);
  --color-surface: var(--surface-card);
  --color-raised: var(--surface-raised);
  --color-hover: var(--surface-hover);
  --color-selected: var(--surface-selected);
  --color-tile: var(--surface-tile);
  --color-cell-quiet: var(--cell-quiet);
  --color-chart-ink-2: var(--chart-ink-2);
  --color-accent-line: var(--accent-line);
  --color-control: var(--border-control);
  --color-pressed: var(--surface-pressed);
  --color-inverse: var(--surface-inverse);
  --color-overlay: var(--surface-overlay);
  --color-text-1: var(--text-1);
  --color-text-2: var(--text-2);
  --color-text-3: var(--text-3);
  --color-text-disabled: var(--text-disabled);
  --color-text-inverse: var(--text-inverse);
  --color-on-field: var(--text-on-field);
  --color-hair: var(--border-hair);
  --color-faint: var(--border-faint);
  --color-strong: var(--border-strong);
  --color-accent-mark: var(--accent-mark);
  --color-accent-field: var(--accent-field);
  --color-accent-wash: var(--accent-wash);
  --color-accent-tint: var(--accent-tint);
  --color-accent-label: var(--accent-label);
  --color-warn-text: var(--warn-text);
  --color-fail-text: var(--fail-text);
  --color-on-accent-field: var(--accent-on-field);
  --color-warn: var(--warn-mark);
  --color-fail: var(--fail-mark);
  --color-button-primary-hover: var(--button-primary-hover);
  --color-button-secondary-hover: var(--button-secondary-hover);
  --color-ghost: var(--button-ghost);
  --color-ghost-hover: var(--button-ghost-hover);
  --color-well: var(--surface-card);
  --color-frame: var(--line-frame);
  --color-line-row: var(--line-row);
  --color-transparent: transparent;
  --color-current: currentColor;

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  --font-weight-normal: var(--weight-body);
  --font-weight-medium: var(--weight-medium);
  --font-weight-semibold: var(--weight-strong);
  --font-weight-bold: 700;

  /* The usual size names (text-sm, text-base) mapped to Quartz roles (size, line-height). Prefer the type-* utilities. */
  --text-xs: 12px;
  --text-xs--line-height: 16px;
  --text-sm: 14px;
  --text-sm--line-height: 20px;
  --text-base: 16px;
  --text-base--line-height: 22px;
  --text-lg: 20px;
  --text-lg--line-height: 24px;
  --text-xl: 24px;
  --text-xl--line-height: 28px;
  --text-2xl: 32px;
  --text-2xl--line-height: 36px;
  --text-3xl: 40px;
  --text-3xl--line-height: 44px;

  --tracking-display: var(--tracking-display);
  --tracking-heading: var(--tracking-heading);
  --tracking-body: var(--tracking-body);
  --tracking-text: var(--tracking-text);
  --tracking-normal: 0em;

  --radius-none: var(--radius-0);
  --radius-inner: var(--radius-inner);
  --radius-soft: var(--radius-soft);
  --radius-frame: var(--radius-frame);
  --radius-xs: var(--radius-inner);
  --radius-sm: var(--radius-inner);
  --radius-md: var(--radius-soft);
  --radius-lg: var(--radius-frame);
  --radius-xl: var(--radius-frame);
  --radius-full: var(--radius-full);

  /* No shadows except overlays. shadow-xs and shadow-sm stay empty so a default shadow draws nothing. */
  --shadow-xs: 0 0 #0000;
  --shadow-sm: 0 0 #0000;
  --shadow-md: var(--elev-overlay);
  --shadow-lg: var(--elev-overlay);
  --shadow-overlay: var(--elev-overlay);

  --ease-step: var(--ease-step);

  --animate-run: quartz-spin var(--dur-run) linear infinite;
  --animate-slide: quartz-slide var(--dur-slide) var(--ease-step) infinite;
  --animate-spin: quartz-spin var(--dur-spin) var(--ease-spin) infinite;
}

/* One utility per type role. Text at 14px and below tracks at 0 (--tracking-text); 16px text takes
   --tracking-body and display sizes stay negative. Numeric roles turn on tabular figures. The font shorthand resets the width axis, so set it after. */
@utility type-display-xl { font: var(--type-display-xl); letter-spacing: var(--tracking-display); font-variation-settings: var(--width-normal); }
@utility type-display-lg { font: var(--type-display-lg); letter-spacing: var(--tracking-display); font-variation-settings: var(--width-normal); }
@utility type-display { font: var(--type-display); letter-spacing: var(--tracking-display); font-variation-settings: var(--width-normal); }
@utility type-heading-lg { font: var(--type-heading-lg); letter-spacing: var(--tracking-heading); font-variation-settings: var(--width-normal); }
@utility type-heading { font: var(--type-heading); letter-spacing: var(--tracking-heading); font-variation-settings: var(--width-normal); }
@utility type-heading-sm { font: var(--type-heading-sm); letter-spacing: var(--tracking-heading); font-variation-settings: var(--width-normal); }
@utility type-heading-xs { font: var(--type-heading-xs); letter-spacing: var(--tracking-heading); font-variation-settings: var(--width-normal); }
@utility type-body-lg { font: var(--type-body-lg); letter-spacing: var(--tracking-body); font-variation-settings: var(--width-normal); }
@utility type-body { font: var(--type-body); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal); }
@utility type-body-sm { font: var(--type-body-sm); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal); }
@utility type-button { font: var(--type-button); letter-spacing: var(--tracking-body); font-variation-settings: var(--width-normal); }
@utility type-label { font: var(--type-label); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal); }
@utility type-label-sm { font: var(--type-label-sm); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal); font-feature-settings: var(--features-data); }
@utility type-code { font: var(--type-code); letter-spacing: 0; font-variant-numeric: tabular-nums; }
@utility type-tag { font: var(--type-tag); letter-spacing: 0; font-variant-numeric: tabular-nums; }
@utility type-code-sm { font: var(--type-code-sm); letter-spacing: 0; font-variant-numeric: tabular-nums; }
@utility type-code-touch { font: var(--type-code-touch); letter-spacing: 0; font-variant-numeric: tabular-nums; }
@utility type-code-display { font: var(--type-code-display); font-feature-settings: var(--features-data); }
@utility type-stat-xl { font: var(--type-stat-xl); letter-spacing: 0; font-variation-settings: var(--width-normal); font-feature-settings: var(--features-data); }
@utility type-stat-lg { font: var(--type-stat-lg); letter-spacing: 0; font-variation-settings: var(--width-normal); font-feature-settings: var(--features-data); }
@utility type-stat { font: var(--type-stat); letter-spacing: 0; font-variation-settings: var(--width-normal); font-feature-settings: var(--features-data); }
@utility type-state-word { font: var(--type-state-word); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal); }
@utility data { font-feature-settings: var(--features-data); }

/* Focus. base.css rings every :focus-visible element; these are that same ring, from the same tokens, for the
   places it has to sit elsewhere. focus-ring: on a box that shows the focus of the bare control inside it
   (has-[[data-control]:focus-visible]:focus-ring), an open trigger or a cell the grid has made current.
   focus-ring-inset: the ring inside the element's own edge, where a container would clip it or a neighbour's shared
   line would collide with an offset ring (cells in a strip, rows, menu items, day cells). */
@utility focus-ring { outline: var(--line-focus) solid var(--border-focus); outline-offset: var(--focus-offset); }
@utility focus-ring-inset { outline: var(--line-focus) solid var(--border-focus); outline-offset: calc(var(--line-focus) * -1); }
/* touch-target: a coarse pointer gets a 44px (--control-lg) hit area centred on a smaller control, drawn on ::after so the
   layout and the fine-pointer look stay as they are. The host must be positioned and must not use ::after itself (a key
   button does, so it keeps its own size). Neighbours closer than 44px overlap, and the later one in the DOM takes the tap. */
@utility touch-target {
  @media (pointer: coarse) {
    &::after { content: ""; position: absolute; top: 50%; left: 50%; translate: -50% -50%; width: max(100%, var(--control-lg)); height: max(100%, var(--control-lg)); }
  }
}

/* focus-ring-ink: on an ink-filled cell that sits edge to edge (a checked segment, a pressed group member, a selected
   day, a focused chip), where an ink ring would vanish into the fill. A 2px paper ring 4px inside the cell, leaving 2px
   of ink outside it, so the ring reads ink, paper, ink: 17.1:1 for paper on ink in light, the same pair flipped in dark. */
@utility focus-ring-ink { outline: var(--line-focus) solid var(--paper); outline-offset: calc(var(--line-focus) * -2); }

/* Lines. A component draws its edges on pseudo-elements, so a line never takes layout and neighbours can meet on one
   pixel. An element that sets --frame-color recolours its own edge; nothing else changes a frame's colour. */

/* frame: the one edge of a component's root. The root isolates, so its edge sits over its own rows, washes and sticky
   heads, and clips, so a row's wash follows the rounded corner. Put it on a wrapper that does not scroll: a ::before inside
   a scroller scrolls away with the content. --frame-radius is registered as non-inheriting, so a frame reads only
   the radius set on itself and never the one a parent frame set for its own corners. */
@property --frame-radius { syntax: "*"; inherits: false; }
@utility frame {
  position: relative;
  isolation: isolate;
  overflow: clip;
  border-radius: var(--frame-radius, var(--radius-frame));
  &::before {
    content: ""; position: absolute; inset: 0; pointer-events: none; z-index: var(--z-cover);
    border: 1px solid var(--frame-color, var(--line-frame)); border-radius: inherit;
  }
}

/* frame-shared: cells side by side with no gap (chip strip, toolbar, segmented control, pagination). Each cell draws
   its start, top and bottom edges and the last cell also its end, so no pixel is painted twice and a translucent edge
   keeps its own alpha. Only the outer corners round. */
@utility frame-shared {
  position: relative;
  border-radius: var(--radius-0);
  &::before {
    content: ""; position: absolute; inset: 0; pointer-events: none;
    border: 1px solid var(--frame-color, var(--line-control)); border-inline-end-width: 0; border-radius: inherit;
  }
  &:first-child { border-start-start-radius: var(--radius-soft); border-end-start-radius: var(--radius-soft); }
  &:last-child { border-start-end-radius: var(--radius-soft); border-end-end-radius: var(--radius-soft); }
  &:last-child::before { border-inline-end-width: 1px; }
}

/* frame-shared-y: frame-shared for a column of cells (a vertical button group). Each cell draws its start, end and top
   edges and the last cell also its bottom; only the top and bottom outer corners round. */
@utility frame-shared-y {
  position: relative;
  border-radius: var(--radius-0);
  &::before {
    content: ""; position: absolute; inset: 0; pointer-events: none;
    border: 1px solid var(--frame-color, var(--line-control)); border-block-end-width: 0; border-radius: inherit;
  }
  &:first-child { border-start-start-radius: var(--radius-soft); border-start-end-radius: var(--radius-soft); }
  &:last-child { border-end-start-radius: var(--radius-soft); border-end-end-radius: var(--radius-soft); }
  &:last-child::before { border-block-end-width: 1px; }
}

/* frame-ink: an ink edge on one control or cell, for hover, pressed and open (hover:frame-ink, aria-pressed:frame-ink).
   In a strip the cell also draws its end edge over its neighbour's start edge and rises above it, so both its sides
   read ink. */
@utility frame-ink {
  --frame-color: var(--ink);
  z-index: var(--z-raised);
  &:where(.frame-shared:not(:last-child))::before { border-inline-end-width: 1px; inset-inline-end: -1px; }
  &:where(.frame-shared-y:not(:last-child))::before { border-block-end-width: 1px; inset-block-end: -1px; }
}

/* frame-out: an edge 1px outside the box, for an element that must sit on its neighbour's line. On a translucent line
   it stacks, so use it where it replaces the line below it (a selected tab over its panel, which hides the panel's
   line under the tab with paper). */
@utility frame-out {
  position: relative;
  &::before {
    content: ""; position: absolute; inset: -1px; pointer-events: none; z-index: var(--z-raised);
    border: 1px solid var(--frame-color, var(--line-frame)); border-radius: inherit;
  }
}

/* key: a button as a lit object (tokens --key-*). One element, one light from the top: the body (background), the
   edge (box-shadow: lip, base, rim, ring, drops) and a sheen (::after: a 1px glint and a soft top dome). Press sinks
   it: the lift becomes an inner shadow and the sheen dims. The primary adds a hover light on ::before (the body-hover
   fading in); the secondary takes its hover wash as a background layer, so ::before stays free for frame-shared when
   it joins a button group. The label stays above the layers through isolation. Disabled drops the light layers. */
@utility key {
  isolation: isolate;
  &::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: -1; transition: opacity var(--dur-fast) var(--ease-step); }
  &:active:not([data-disabled])::after { opacity: 0.4; }
  &[data-disabled]::after { display: none; }
  @media (forced-colors: active) { &::after { display: none; } }
}
@utility key-primary {
  background: var(--key-primary-body); box-shadow: var(--key-primary-edge);
  &::before { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: -1; opacity: 0; background: var(--key-primary-body-hover); transition: opacity var(--dur-fast) var(--ease-step); }
  &:hover:not([data-disabled])::before { opacity: 1; }
  &[data-disabled]::before { display: none; }
  @media (forced-colors: active) { &::before { display: none; } }
  &::after { background: var(--key-primary-sheen); }
  &:active:not([data-disabled]) { box-shadow: var(--key-primary-edge-press); }
}
@utility key-secondary {
  background: var(--key-secondary-body); box-shadow: inset 0 0 0 1px var(--frame-color, var(--line-control)), var(--key-secondary-edge);
  transition: background-color var(--dur-fast) var(--ease-step);
  &:hover:not([data-disabled]) { background: linear-gradient(var(--key-secondary-body-hover), var(--key-secondary-body-hover)), var(--key-secondary-body); }
  &::after { background: var(--key-secondary-sheen); }
  &:active:not([data-disabled]) { box-shadow: inset 0 0 0 1px var(--frame-color, var(--line-control)), var(--key-secondary-edge-press); }
  /* A toggle that is on is an ink key held down. */
  &[data-pressed]:not([data-disabled]) { background: var(--key-primary-body); box-shadow: var(--key-primary-edge-press); }
}

/* control-edge: the 1px edge of a control that cannot take a pseudo-element (input, textarea, select) or that sits
   alone (a field box, a trigger). An inset shadow, so it never takes layout. It reads --frame-color on the element
   itself, so hover:[--frame-color:var(--line-frame)] or an invalid state recolours it. It is not a token because a var() inside a
   token resolves where the token is declared, so a --frame-color set on the control would never reach it. */
@utility control-edge { box-shadow: inset 0 0 0 1px var(--frame-color, var(--line-control)), var(--control-lift, var(--elev-control)); }

/* rule-row: the faint rule under a row or a header. The last row drops it, because the frame's edge is right below.
   An open row ([data-open], one per list) takes a soft wash and no ink lines. */
@utility rule-row {
  box-shadow: inset 0 -1px 0 var(--line-row);
  &:last-child { box-shadow: none; }
  &:where([data-open]) { background-color: var(--surface-hover); }
}
/* rule-col: the same rule on a cell's start edge, for cells side by side inside one frame (a stat strip, a toolbar in a
   table). rule-top: the rule above a footer. */
@utility rule-col { box-shadow: inset 1px 0 0 var(--line-row); &:dir(rtl) { box-shadow: inset -1px 0 0 var(--line-row); } }
@utility rule-top { box-shadow: inset 0 1px 0 var(--line-row); }
/* rule-row-frame: the frame-weight rule under a bar that stands alone (a page header, a sidebar header, a tab strip), so it
   keeps its line as the last child, where rule-row would drop it. */
@utility rule-row-frame { box-shadow: inset 0 -1px 0 var(--line-frame); }

/* wash-row: the faint fail wash on a row (a failed table, list, log or timeline row): the accent wash at 40%, and 60% under the
   pointer (wash-row-hover, as hover:wash-row-hover). It reads --accent-wash on the element itself, since a status scope sets that
   on the row, which is why this is a utility and not a token. */
@utility wash-row { background-color: color-mix(in oklab, var(--accent-wash) 40%, transparent); }
@utility wash-row-hover { background-color: color-mix(in oklab, var(--accent-wash) 60%, transparent); }

/* frame-head: the one header of a framed component (Panel, Card, table, chart, code, log, timeline, JSON, a response's
   code block). 40px (--row), the title and meta 16px from the start edge, and one action at the end at xs (24px,
   wrap it in ButtonSize xs or use icon-xs) 8px from the end edge: it takes the 8px as soon as it holds a button, radio or combobox.
   frame-head-action is that action slot. The rule under it is the caller's (rule-row), because a Panel's header sits on
   the grey and has none. */
@utility frame-head {
  display: flex; align-items: center; gap: var(--space-2); min-width: 0; flex-shrink: 0;
  min-height: var(--row); padding-inline: var(--space-4);
  &:has(:is(button, [role="radio"], [role="combobox"])) { padding-inline-end: var(--space-2); }
}
@utility frame-head-action { margin-inline-start: auto; display: flex; flex-shrink: 0; align-items: center; gap: var(--space-1); }

/* frame-foot: the one footer of a framed component, 44px (--control-lg) with the text 16px from the start edge and
   actions at sm (28px, wrap in ButtonSize sm) 8px from the end edge. Content sits at the start; add justify-end where it
   holds only actions. Buttons keep their size on a touch screen too: the 44px footer already gives them room, and a
   footer of 44px-tall buttons reads as a phone form, not the card. The rule above is the caller's (rule-top). */
@utility frame-foot {
  display: flex; align-items: center; gap: var(--space-2); min-width: 0;
  min-height: var(--control-lg); padding: var(--space-2) var(--space-4);
  &:has(button) { padding-inline-end: var(--space-2); }
}

/* The one list recipe. Every popup that lists things (dropdown menu, select, combobox, command, the table's menus, breadcrumb,
   button group, filter bar, the prompt's @ and / list) draws its rows, labels and rules from these four, so a row is the same
   32px (--row-sm) tall, 8px from its edges, with a 8px gap and 16px icons wherever it appears. The base is wrapped in :where()
   so any class on the item (pe-8 for a trailing check, items-start for a second line) still wins. The surface and the motion of
   the popup are lib/overlay's, not these.
   menu-popup: the geometry of a popup that scrolls as one block, at least --menu-min wide, 4px inside its edge.
   menu-item: a row. The highlighted one (data-highlighted, set by the list itself) takes the hover wash; data-variant="destructive"
   reads in the fail word at rest and takes the fail wash. A coarse pointer grows it to the 44px touch target; forced colours paints
   the highlighted row with Highlight and the disabled one with GrayText. A leading icon steps back to text-2.
   menu-label: the heading of a group of rows. menu-separator: the hairline between groups, edge to edge of the 4px inset. */
@utility menu-popup {
  :where(&) { min-width: var(--menu-min); max-width: min(var(--overlay), var(--available-width)); max-height: var(--available-height); padding: var(--space-1); overflow-x: hidden; overflow-y: auto; overscroll-behavior: contain; }
  &:focus-visible { outline: none; }
}
@utility menu-item {
  :where(&) {
    position: relative; display: flex; align-items: center; gap: var(--space-2); min-height: var(--row-sm);
    padding: calc(var(--space-1) * 1.5) var(--space-2); border-radius: var(--radius-inner);
    font: var(--type-label); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal);
    color: var(--text-1); cursor: default; user-select: none; outline: none;
  }
  :where(& > svg) { flex-shrink: 0; pointer-events: none; color: var(--text-2); }
  &[data-highlighted] { background-color: var(--surface-hover); }
  &[data-variant="destructive"] { color: var(--fail-text); }
  &[data-variant="destructive"] > svg { color: inherit; }
  &[data-variant="destructive"][data-highlighted] { background-color: var(--accent-wash); }
  &[data-disabled] { cursor: not-allowed; color: var(--text-disabled); }
  @media (pointer: coarse) { :where(&) { min-height: var(--control-lg); } }
  @media (forced-colors: active) {
    &[data-disabled] { color: GrayText; }
    &[data-highlighted] { forced-color-adjust: none; background-color: Highlight; color: HighlightText; }
    &[data-highlighted] svg { color: HighlightText; }
  }
}
@utility menu-label {
  :where(&) {
    padding: var(--space-2) var(--space-2) var(--space-1); color: var(--text-3);
    font: var(--type-label-sm); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal); font-feature-settings: var(--features-data);
  }
}
@utility menu-separator {
  :where(&) { height: 1px; margin: var(--space-1) calc(var(--space-1) * -1); background-color: var(--line-row); }
  @media (forced-colors: active) { background-color: CanvasText; }
}

/* search-row: the search field that sits inside a component (Command, the prompt's command list, a log's filter, a JSON tree's
   search), not in a form. One row, --row (40px) tall, with the icon 16px from the start edge in text-3, 8px to the text, and
   room at the end for a count and a clear button. It has no box of its own, so focus is the field's ink edge drawn inside the
   row (the same ink as a field's edge, with no halo to clip). Put it on the label or div that holds the icon and the input;
   mark the input data-control (base.css rings every other focusable) and give it search-field. The rule under the row is the
   caller's (rule-row) and the edge replaces it while the field has focus. */
@utility search-row {
  :where(&) {
    display: flex; align-items: center; gap: var(--space-2); min-height: var(--row); min-width: 0; flex-shrink: 0;
    padding-inline: var(--space-4) var(--space-2);
    transition: box-shadow var(--dur-fast) var(--ease-step);
  }
  &:has([data-control]:focus-visible) { box-shadow: inset 0 0 0 1px var(--border-focus); }
  :where(& > svg) { flex-shrink: 0; color: var(--text-3); }
}
@utility search-field {
  :where(&) {
    height: 100%; min-width: 0; flex: 1 1 0%; background: transparent; color: var(--text-1);
    font: var(--type-label); letter-spacing: var(--tracking-text); font-variation-settings: var(--width-normal);
  }
  &::placeholder { color: var(--text-3); }
  &::-webkit-search-cancel-button { display: none; }
  /* 16px stops iOS from zooming into the field on focus. */
  @media (pointer: coarse) { font-size: 16px; }
}

/* well: the grey field, only for code, output and read-only values inside a frame. No line of its own. Padding is the
   caller's, px-4 py-3 by default. */
@utility well { background-color: var(--surface-card); }

/* An indeterminate progress bar: a third of the track slides across it once per --dur-slide, then starts again (animate-slide). */
@keyframes quartz-slide { from { transform: translateX(-100%); } to { transform: translateX(300%); } }

/* A running mark is a 3/4 arc turning once per --dur-run (animate-run). */
@keyframes quartz-spin { to { transform: rotate(1turn); } }

/* Native scrollbars take the thumb role, so a thin scrollbar reads in both themes. */
.quartz, .quartz * { scrollbar-color: var(--scrollbar-thumb) transparent; }

/* Toast (ui/toast.tsx): the drain line shrinks to nothing over the toast's timeout. */
@keyframes quartz-toast-drain { from { scale: 1 1; } to { scale: 0 1; } }

/* fade-y and fade-x: a scroller fades to nothing over --fade-edge at each edge that has more behind it, as its data-fade says
   (start, end or both). Something that measures the scroll position sets data-fade (lib/overlay's useScrollFade for a
   vertical list, the tab list for a sideways one). fade-x reads the sides from --fade-from and --fade-to (left and right
   unless the element sets them, as an RTL tab list does). Put it on the element that scrolls, never on a popup, where the
   mask would also cut the shadow. */
@utility fade-y {
  &[data-fade="end"] { mask-image: linear-gradient(to bottom, black calc(100% - var(--fade-edge)), transparent); }
  &[data-fade="start"] { mask-image: linear-gradient(to top, black calc(100% - var(--fade-edge)), transparent); }
  &[data-fade="both"] { mask-image: linear-gradient(to bottom, transparent, black var(--fade-edge), black calc(100% - var(--fade-edge)), transparent); }
}
@utility fade-x {
  &[data-fade="start"] { mask-image: linear-gradient(to var(--fade-to, right), transparent, black var(--fade-edge)); }
  &[data-fade="end"] { mask-image: linear-gradient(to var(--fade-from, left), transparent, black var(--fade-edge)); }
  /* Two masks intersect, so both edges fade. */
  &[data-fade="both"] {
    mask-image: linear-gradient(to var(--fade-to, right), transparent, black var(--fade-edge)), linear-gradient(to var(--fade-from, left), transparent, black var(--fade-edge));
    mask-composite: intersect; -webkit-mask-composite: source-in;
  }
}

/* scroll-fade-y: a scrolling list fades to nothing over --fade-edge at each edge that has more behind it.
   Two scroll-driven animations ride two registered lengths into one mask, the top one opening over the first
   24px of scroll and the bottom one closing over the last 24px. A list that does not scroll has no active
   timeline, so both lengths stay 0 and nothing fades; a browser without scroll timelines shows no fade at
   all. Put it on the element that scrolls, never on a popup, where the mask would also cut the shadow. */
@property --fade-top { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --fade-bottom { syntax: "<length>"; inherits: false; initial-value: 0px; }
@keyframes quartz-fade-top { from { --fade-top: 0px; } to { --fade-top: var(--fade-edge); } }
@keyframes quartz-fade-bottom { from { --fade-bottom: var(--fade-edge); } to { --fade-bottom: 0px; } }
@utility scroll-fade-y {
  mask-image: linear-gradient(to bottom, transparent, black var(--fade-top), black calc(100% - var(--fade-bottom)), transparent);
  @supports (animation-timeline: scroll()) {
    animation: quartz-fade-top linear both, quartz-fade-bottom linear both;
    animation-timeline: scroll(self), scroll(self);
    animation-range: 0 var(--fade-edge), calc(100% - var(--fade-edge)) 100%;
  }
}
